-- Prepared only: run after approval on the selected database branch.
BEGIN;
CREATE TABLE IF NOT EXISTS console066_sessions (
 token_hash text PRIMARY KEY, expires_at timestamptz NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS console066_login_limits (
 bucket text PRIMARY KEY, window_start timestamptz NOT NULL, attempts integer NOT NULL
);
CREATE TABLE IF NOT EXISTS console066_leads (
 id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 country text NOT NULL, name text NOT NULL, type text NOT NULL, genres text NOT NULL,
 evidence text NOT NULL, source_url text NOT NULL, verification text NOT NULL,
 notes text NOT NULL DEFAULT '', message text NOT NULL DEFAULT '',
 status text NOT NULL DEFAULT 'Por verificar' CHECK(status IN ('Por verificar','Listo para contactar','Contactado','En conversación','Cerrado','No contactar')),
 approved_message text, approved_at timestamptz,
 version integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(name,source_url),
 CHECK(approved_message IS NULL OR (approved_message=message AND length(message)>0)),
 CHECK((approved_message IS NULL)=(approved_at IS NULL))
);
CREATE TABLE IF NOT EXISTS console066_tasks (
 id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text NOT NULL UNIQUE,
 description text NOT NULL, dependency text NOT NULL,
 status text NOT NULL DEFAULT 'Pendiente' CHECK(status IN ('Pendiente','En preparación','Listo para revisar','Completado')),
 version integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS console066_audit (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, entity text NOT NULL,
 entity_id integer NOT NULL, action text NOT NULL, detail jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS console066_sessions_expiry ON console066_sessions(expires_at);
COMMIT;
